var n=`0962-japanese-curry-rice`;var t=`world-0962`;var a=`JP`;var r=`east-asia`;var o=4;var s=63;var d={en:`Japanese Curry Rice`,ua:`Японський рис із карі`};var l={en:`Japanese Curry Rice is a Japan dish made with jasmine rice, chicken thigh, yellow onion, potato. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Японський рис із карі, страва кухні країни Японія. Основні складники: рис жасмин, куряче стегно, жовта цибуля, картопля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 22 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 22 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:22,i:[[`jasmine-rice`,420,`g`],[`water`,780,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 13 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 13 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:13,i:[[`chicken-thigh`,530,`g`],[`yellow-onion`,170,`g`],[`potato`,330,`g`],[`carrot`,230,`g`],[`canola-oil`,40,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 23 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 23 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:23,i:[[`japanese-curry-roux`,135,`g`],[`water`,830,`ml`]]},{en:`Arrange the prepared cooked components and listed toppings in a serving dish, keeping hot foods hot and chilled components cold until serving.`,ua:`Складіть готові приготовлені компоненти й зазначені додатки в посуді для подавання, підтримуючи гаряче гарячим, а холодне охолодженим.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`pickled-ginger`,40,`g`]]}];var u={slug:n,id:t,country:`JP`,region:r,servings:4,minutes:63,title:d,text:l,steps:g};export{a as country,u as default,t as id,s as minutes,r as region,o as servings,n as slug,g as steps,l as text,d as title};